const leads = [
  { leadId: "DEMO-001", name: "Alice Example", email: "alice@example.test", message: "Need a quote this week for 12 stores" },
  { leadId: "DEMO-002", name: "Bob Example", email: "bob@example.test", message: "Connect our spreadsheet and shared inbox" },
  { leadId: "DEMO-003", name: "Alice Duplicate", email: "ALICE@example.test", message: "Repeated submission" },
  { leadId: "DEMO-004", name: "Invalid Example", email: "invalid-email", message: "Please contact me" },
];
return leads.map(lead => ({ json: lead }));

const source = $input.all().map(item => item.json);
const seen = new Set();
const accepted = [];
const rejected = [];
for (const lead of source) {
  const email = String(lead.email ?? "").trim().toLowerCase();
  const record = { leadId: String(lead.leadId ?? ""), name: String(lead.name ?? "").trim(), email, message: String(lead.message ?? "").trim() };
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    rejected.push({ leadId: record.leadId, reason: "invalid_email" });
    continue;
  }
  if (seen.has(email)) {
    rejected.push({ leadId: record.leadId, reason: "duplicate_in_batch" });
    continue;
  }
  seen.add(email);
  accepted.push(record);
}
return [{ json: { inputCount: source.length, accepted, rejected } }];

const state = $input.first().json;
state.accepted = state.accepted.map(lead => ({
  ...lead,
  priority: /quote|urgent|this week/i.test(lead.message) ? "high" : "standard",
  category: /spreadsheet|sheet|inbox/i.test(lead.message) ? "integration" : "new_project",
}));
return [{ json: state }];

const state = $input.first().json;
state.mockSheetRows = state.accepted.map(lead => ({
  leadId: lead.leadId, name: lead.name, email: lead.email,
  priority: lead.priority, category: lead.category,
}));
return [{ json: state }];

const state = $input.first().json;
state.mockNotifications = state.accepted.map(lead => ({
  to: "demo-ops@example.test", leadId: lead.leadId, priority: lead.priority,
}));
state.mockAlerts = state.rejected
  .filter(item => item.reason === "invalid_email")
  .map(item => ({ to: "demo-ops@example.test", leadId: item.leadId, reason: item.reason }));
return [{ json: state }];

const state = $input.first().json;
return [{ json: {
  demo: "synthetic_lead_intake",
  externalMessagesSent: 0,
  counts: {
    input: state.inputCount,
    accepted: state.accepted.length,
    duplicateInBatch: state.rejected.filter(x => x.reason === "duplicate_in_batch").length,
    invalid: state.rejected.filter(x => x.reason === "invalid_email").length,
    mockSheetRows: state.mockSheetRows.length,
    mockNotifications: state.mockNotifications.length,
    mockAlerts: state.mockAlerts.length,
  },
  mockSheetRows: state.mockSheetRows,
  mockNotifications: state.mockNotifications,
  mockAlerts: state.mockAlerts,
  rejected: state.rejected,
}}];
